-- Fakt kartochkalari orqa tomonining ruscha matni — 66-partiya:
-- Habib Abdullayev, Hakim at-Termiziy, Hamid Olimjon.

UPDATE fact_cards SET detail_ru = 'Хабиб Абдуллаев родился 31 августа 1912 года в городе Ош. Позже он стал одним из самых известных учёных-геологов Узбекистана. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2060;
UPDATE fact_cards SET detail_ru = 'В 1935 году он окончил горный факультет Среднеазиатского индустриального института и работал начальником геолого-разведочной партии. С 1940 года был доцентом в этом же институте. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2061;
UPDATE fact_cards SET detail_ru = 'В 1946 году Хабиб Абдуллаев защитил докторскую диссертацию на тему «Геология шеелитовых скарнов Средней Азии». А в 1947 году стал академиком Академии наук Узбекистана. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2062;
UPDATE fact_cards SET detail_ru = 'С 1947 года он был вице-президентом Академии наук Узбекистана, в 1952–1955 годах — председателем отделения технических и геолого-химических наук, а с 1956 года и до конца жизни — президентом академии. В то же время он был директором Института геологии. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2063;
UPDATE fact_cards SET detail_ru = 'Хабиб Абдуллаев написал более 130 научных работ, в их числе семь монографий. Его сочинение «Генетическая связь оруденения с гранитоидными интрузиями» переведено на немецкий, английский и китайский языки, а с 1960 года он был членом Геологического общества Франции и Королевского минералогического общества Великобритании. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2064;
UPDATE fact_cards SET detail_ru = 'Он исследовал геологическое строение Лянгарского вольфрамо-молибденового месторождения, развил теорию эндогенного рудообразования и определил пути образования месторождений вольфрама, олова, цветных и чёрных металлов. Он первым выделил Среднюю Азию как отдельную металлогеническую провинцию. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2065;
UPDATE fact_cards SET detail_ru = 'Под его руководством семь человек защитили докторские и двадцать восемь — кандидатские диссертации. Он основал первую кафедру петрологии и металлогении на геолого-разведочном факультете ТашПИ и положил начало «Геологическому журналу Узбекистана». Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2066;
UPDATE fact_cards SET detail_ru = 'Хабиб Абдуллаев умер 20 июня 1962 года в Ташкенте и погребён на Чигатайском кладбище. Позже его имя было присвоено Институту геологии и геофизики Академии наук Узбекистана, одной из станций Ташкентского метро и нескольким улицам, а в 1970 году за монографию «Металлогения» ему была присуждена Государственная премия имени Беруни. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2067;

UPDATE fact_cards SET detail_ru = 'Точный год его рождения в источниках не указан: учитывая, что учёный прожил долгую жизнь — 116 или 120 лет, — считается, что он родился примерно в середине VIII века (между 750 и 760 годами) в городе Термезе. Прозвище «аль-Хаким» означает мудреца, постигающего внутренние, сокровенные смыслы знания. Источник: Ziyouz.com, статья «Аль-Хаким ат-Термези».' WHERE id = 2186;
UPDATE fact_cards SET detail_ru = 'Науке о хадисах он учился у отца, а позже брал уроки у таких учёных, как Кутайба ибн Саид ас-Сакафи, Салих ибн Абдуллах ат-Термези, Абу Тураб ан-Нахшаби, Ахмад ибн Хизравайх и Яхья ибн Маоз ар-Рази. Согласно преданию, по благодати молитвы его матери светлый шейх — Хизр, мир ему, — каждый день давал ему уроки в разных науках. Источник: Ziyouz.com, статья «Аль-Хаким ат-Термези».' WHERE id = 2187;
UPDATE fact_cards SET detail_ru = 'Когда ему шёл двадцать восьмой год, он через Ирак отправился в Мекку, совершил обряд хаджа, а возвращаясь из странствия, положил себе выучить Коран наизусть. В источниках отмечено, что он бывал в Куфе, Басре, Нишапуре и Балхе. Источник: Ziyouz.com, статья «Аль-Хаким ат-Термези».' WHERE id = 2188;
UPDATE fact_cards SET detail_ru = 'По некоторым источникам, учёный создал около четырёхсот сочинений, из которых до нас дошло около шестидесяти. Сегодня его рукописи хранятся в библиотеках Парижа, Каира, Дамаска, Александрии, Стамбула и Лондона; в Национальной библиотеке Парижа есть двенадцать его сочинений. Источник: Ziyouz.com, статья «Аль-Хаким ат-Термези».' WHERE id = 2189;
UPDATE fact_cards SET detail_ru = '«Хатм уль-авлия» состоит из предисловия и двадцати девяти глав и положило начало учению о святости. Позже великий суфий Ибн аль-Араби, вдохновившись этим сочинением, написал в книгах «Джаваб уль-мустаким» и «Аль-Футухат аль-Маккия» ответы на приведённые в нём сто пятьдесят пять вопросов. Источник: Ziyouz.com, статья «Аль-Хаким ат-Термези».' WHERE id = 2190;
UPDATE fact_cards SET detail_ru = 'Благодаря его ученикам и последователям в суфизме позже возникло течение, названное некоторыми учёными «аль-хакимия ва-т-термизия». Это течение связано с именем и учением самого учёного. Источник: Ziyouz.com, статья «Аль-Хаким ат-Термези».' WHERE id = 2191;
UPDATE fact_cards SET detail_ru = 'После того как были обнародованы некоторые сочинения, написанные им в Термезе, часть людей выступила против него, и учёный был вынужден несколько лет жить в Балхе. Правитель Балха взял с него обещание не говорить о любви к Богу. Источник: Ziyouz.com, статья «Аль-Хаким ат-Термези».' WHERE id = 2192;
UPDATE fact_cards SET detail_ru = 'По сведениям Хаджи Халифы в сочинении «Кашф аз-зунун» и по надписи на надгробии, он умер в 255 году хиджры (869 год). А египетский учёный Абдулфаттах Абдуллах Барака считает, что он умер в 320 году хиджры (932 год) в возрасте 112 лет. Его мавзолей находится близ города Термеза, на берегу Амударьи. Источник: Ziyouz.com, статья «Аль-Хаким ат-Термези».' WHERE id = 2193;

UPDATE fact_cards SET detail_ru = 'Хамид Алимджан родился 12 декабря 1909 года в городе Джизаке. Сперва он учился в начальной школе имени Нариманова. Источник: Ziyouz.com' WHERE id = 2036;
UPDATE fact_cards SET detail_ru = 'В 1923–1926 годах Хамид Алимджан учился в Самаркандском педагогическом училище, а в 1926–1931 годах — в Педагогической академии. Источник: Ziyouz.com' WHERE id = 2037;
UPDATE fact_cards SET detail_ru = 'Первый стихотворный сборник Хамида Алимджана «Весна» был издан в 1929 году. Есть у него и сборники «Огненные волосы» (1931), «Смерть врагу» (1932), «Скачки» (1932), «Ночь на реке» (1936), «Край» (1939), «Счастье» (1940). Источник: Ziyouz.com' WHERE id = 2038;
UPDATE fact_cards SET detail_ru = '«Зайнаб и Аман» — известная поэма Хамида Алимджана, написанная в 1930-е годы. Есть у него и поэма «Повесть о двух девушках» (1935–1937). Источник: Ziyouz.com' WHERE id = 2039;
UPDATE fact_cards SET detail_ru = '«Ойгуль и Бахтияр» написана в 1937 году, а «Семург» — в 1939-м. Поэт создал и такие баллады, как «Боец Турсун», «Слёзы Роксаны». Источник: Ziyouz.com' WHERE id = 2040;
UPDATE fact_cards SET detail_ru = 'Хамид Алимджан написал стихотворную драму «Муканна» и драму «Преступление». Он переложил на узбекский язык сочинения таких писателей, как Пушкин, Толстой, Горький, Маяковский, Лермонтов, Шевченко. Источник: Ziyouz.com' WHERE id = 2041;
UPDATE fact_cards SET detail_ru = 'С 1939 года и до конца жизни Хамид Алимджан возглавлял Союз писателей Узбекистана. В 1943 году он стал членом-корреспондентом Академии наук Узбекистана. Источник: Ziyouz.com' WHERE id = 2042;
UPDATE fact_cards SET detail_ru = 'Хамид Алимджан погиб 3 июля 1944 года в автомобильной катастрофе. Ему было всего тридцать четыре года. Источник: Ziyouz.com' WHERE id = 2043;
